package vn.hust.restaurant.repository;
import java.sql.*;import java.time.*;import java.util.*;import vn.hust.restaurant.config.Database;import vn.hust.restaurant.model.Promotion;
public class PromotionRepository{
 public List<Promotion> active()throws SQLException{return list(true);}public List<Promotion> all()throws SQLException{return list(false);}private List<Promotion> list(boolean active)throws SQLException{List<Promotion>o=new ArrayList<>();String s="SELECT MaKM,MaKMCode,TenKM,LoaiKM,GiaTriGiam,DieuKienToiThieu,MucGiamToiDa,NgayBatDau,NgayKetThuc,TrangThai,MaMonMucTieu,SoLuongMua,SoLuongTang FROM KhuyenMai WHERE (?=0 OR (TrangThai='HOAT_DONG' AND CAST(GETDATE() AS DATE) BETWEEN NgayBatDau AND NgayKetThuc)) ORDER BY NgayKetThuc DESC";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(s)){p.setInt(1,active?1:0);try(ResultSet r=p.executeQuery()){while(r.next())o.add(new Promotion(r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getBigDecimal(5),r.getBigDecimal(6),r.getBigDecimal(7),r.getDate(8).toLocalDate(),r.getDate(9).toLocalDate(),"HOAT_DONG".equals(r.getString(10)),Jdbc.integer(r,"MaMonMucTieu"),Jdbc.integer(r,"SoLuongMua"),Jdbc.integer(r,"SoLuongTang")));}}return o;}
}
